const {frozen,run,queries}=require('./index-load-memory.cjs'),{mapped}=require('./mapped-index-performance.cjs'),{journal}=require('./mapped-overlay-performance.cjs'),execute=promisify(execFile),delay=ms=>new Promise(r=>setTimeout(r,ms));
const Memory=koffi.struct('OneMergeMemory',{cb:'uint32',PageFaultCount:'uint32',PeakWorkingSetSize:'size_t',WorkingSetSize:'size_t',QuotaPeakPagedPoolUsage:'size_t',QuotaPagedPoolUsage:'size_t',QuotaPeakNonPagedPoolUsage:'size_t',QuotaNonPagedPoolUsage:'size_t',PagefileUsage:'size_t',PeakPagefileUsage:'size_t',PrivateUsage:'size_t'}),kernel=koffi.load('kernel32.dll'),psapi=koffi.load('psapi.dll'),open=kernel.func('void * __stdcall OpenProcess(uint32,int,uint32)'),close=kernel.func('int __stdcall CloseHandle(void *)'),getMemory=psapi.func('int __stdcall GetProcessMemoryInfo(void *, _Out_ OneMergeMemory *, uint32)');
