 function memory(){const value={cb:koffi.sizeof(Memory)};assert.ok(getMemory(handle,value,value.cb));peakPrivate=Math.max(peakPrivate,value.PeakPagefileUsage);peakResident=Math.max(peakResident,value.PeakWorkingSetSize);return{resident:value.WorkingSetSize,private:value.PrivateUsage,peakPrivate,peakResident};}
 const timer=setInterval(()=>{if(child.exitCode===null)memory();},20);child.stderr.on('data',d=>errors.push(d.toString()));child.stdout.setEncoding('utf8');
 child.stdout.on('data',chunk=>{buffer+=chunk;let end;while((end=buffer.indexOf('\n'))>=0){const v=JSON.parse(buffer.slice(0,end));buffer=buffer.slice(end+1);if(v.ready){ready={...v,readyMs:performance.now()-start};continue;}if(v.merge){events.push({...v.merge,at:performance.now()});continue;}const p=pending.get(v.id);if(!p){if(v.error)errors.push(v.error);continue;}if(v.result?.partial){p.partial={...v.result,wallMs:performance.now()-p.start};continue;}pending.delete(v.id);clearTimeout(p.timer);v.error?p.reject(Error(v.error)):p.resolve({result:v.result,partial:p.partial,wallMs:performance.now()-p.start});}});
 const request=v=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject,start:performance.now(),timer:setTimeout(()=>{pending.delete(id);reject(Error('Store response timeout '+v.type));},45000)});child.stdin.write(JSON.stringify({id,...v})+'\n');});
