 const built=JSON.parse((await execute(exe,['mapped-build',cache,seed,config],{windowsHide:true,timeout:60000,maxBuffer:1024*1024})).stdout.trim());const cases=[...queries.map(query=>({query})),{query:'ext:json package',progressive:true}],baseline=await mapped(exe,seed,cases);
 const report={date:new Date().toISOString(),note:'Diagnostic generation store only. Real complete frozen snapshot, hot disk cache; background writer measured without Index restore. Live profile untouched.',hashes:{exe:hash(await fs.readFile(exe)),source:hash(source.bytes)},build:built,baseline};
 const root=path.join(profile,'files'),put=(p,directory=false)=>({put:{path:p,name:path.basename(p),directory,modified:0,size:0}});await fs.mkdir(root);const initial=[put(root,true)];for(let n=0;n<125;n++){const p=path.join(root,'merge-row-'+String(n).padStart(3,'0')+'.txt');await fs.writeFile(p,'x');initial.push(put(p));}const chinese=path.join(root,'季度报告.PDF');await fs.writeFile(chinese,'x');initial.push(put(chinese));
