  assert.equal(probe.count,built.count);await probe.request({type:'apply',changes:initial});
  const merge=probe.request({type:'compact'}).then(value=>{compactDone=true;return value;});merge.catch(()=>{});
  const first=path.join(root,'merge-row-000.txt'),renamed=path.join(root,'Renamed-row.txt');await fs.rename(first,renamed);const tail=[{remove:first},put(renamed),put(path.join(root,'During-merge.txt')),put(path.join(root,'中文新增.txt'))];await probe.request({type:'apply',changes:tail});allChanges.push(...tail);assert.ok(!compactDone,'Update must be acknowledged during background generation');
  const during=await probe.request({type:'query',scope:1,query:'ext:json package',progressive:true,currentFolder:'D:\\Repositories\\One',fuzzy:true,pinyin:true});assert.ok(!compactDone,'Search must finish while background generation is active');assert.ok(during.partial);assert.ok(during.partial.wallMs<100,'Local results must remain responsive while writing');assert.ok(during.wallMs<=baseline.queries.at(-1).timings.reduce((s,t)=>s+t.wallMs,0)+250,'Background merge must not queue search behind generation');report.duringMerge=during;
  const finished=await merge;report.merge=finished;await delay(100);report.afterMerge=probe.memory();assert.ok(report.afterMerge.peakPrivate<80*1024**2,'Streaming merge must not materialize the full Index');assert.ok(report.afterMerge.private<32*1024**2);assert.ok(report.afterMerge.resident<32*1024**2);
  assert.ok(finished.result.stats.changedRows>0,'Changes received during merging must survive in the new generation delta');
  const changedCases=[...cases,{query:'merge-row',currentFolder:root},{query:'merge-row',currentFolder:root,progressive:true},{query:'jdbg',currentFolder:root},{query:'Renamed-row',currentFolder:root},{query:'During-merge',currentFolder:root},{query:'中文新增',currentFolder:root}];
  const reference=await run(exe,path.join(profile,'reference.bin'),{...source,delta:journal(source,allChanges)},changedCases);assert.equal(finished.result.stats.count,reference.count);report.count=reference.count;report.queries=[];
  for(let i=0;i<changedCases.length;i++){const options=changedCases[i],v=await probe.request({type:'query',scope:1,fuzzy:true,pinyin:true,currentFolder:'D:\\Repositories\\One',...options});assert.equal(v.result.total,reference.queries[i].total);assert.deepEqual(v.result.items,reference.queries[i].items,JSON.stringify(options));if(options.progressive){assert.deepEqual(v.partial.items,reference.queries[i].partial.items);assert.equal(v.partial.total,reference.queries[i].partial.total);}report.queries.push(v);}
  await fs.writeFile(path.join(out,'result.json'),JSON.stringify({...report,result:'MEASURED'},null,2));
  const oldManifest=await fs.readFile(path.join(store,'.one-mapped-current.json'));const extra=Array.from({length:4000},(_,n)=>put(path.join(root,'auto-row-'+String(n).padStart(4,'0')+'.txt')));await probe.request({type:'apply',changes:extra});
